function missingFields(expected, actual, prefix = "") {
  const missing = [];
  for (const [field, rule] of Object.entries(expected)) {
    const path = prefix + field;
    const value = actual?.[field];
    if (value === undefined) missing.push(path);
    else if (rule !== true) missing.push(...missingFields(rule, value, path + "."));
  }
  return missing;
}

