import { schema } from "@zudojs/schema";

const V2 = schema.object({
  orderId: schema.string(),
  total: schema.object({ amountMinor: schema.number().int().positive(), currency: schema.enum(["NGN", "GHS"]) }),
});

function outcome(message: { schemaVersion: number; body: any }): string {
  if (message.schemaVersion > 2) return "parked";
  const body = message.schemaVersion === 1
    ? { orderId: message.body.orderId, total: { amountMinor: message.body.totalKobo, currency: "NGN" } }
    : message.body;
  const result = V2.safeParse(body);
  return result.success ? `handled ${result.data.orderId}` : "dead-letter";
}

