import { createSerializer, deserializeFromEnvelope, serializeToEnvelope } from "@zudojs/serialization";
import type { SerializedEnvelope } from "@zudojs/serialization";

const serializer = createSerializer("json", { preserveTypes: true });

const envelope = serializeToEnvelope({ orderId: "ord_1", amountKobo: 250000n }, serializer, "json", { preserveTypes: true });
const onTheWire = JSON.stringify(envelope);
const received = JSON.parse(onTheWire) as SerializedEnvelope;
const value = deserializeFromEnvelope<{ orderId: string; amountKobo: bigint }>(received, serializer, "json", { preserveTypes: true, strict: true });
console.log(typeof value.amountKobo, value.amountKobo);
console.log(received.metadata.format, received.metadata.version);
